/* Types */
/**  What a key does (tech spec §8.1). In TypeScript, `{ kind: "key-press", key }` and so on. */
export type Action = 
/**  Types a key or shortcut. */
{ kind: "key-press"; 
/**  The key or shortcut. */
key: Shortcut } | 
/**  A key on tap, another on hold. */
{ kind: "mod-tap"; 
/**  What holding it holds. */
hold: Shortcut; 
/**  What tapping it types. */
tap: Shortcut } | 
/**  A key on tap, a layer on hold. */
{ kind: "layer-tap"; 
/**  The layer, by ID. */
layer: number; 
/**  What tapping it types. */
tap: Shortcut } | 
/**  A layer while held. */
{ kind: "momentary"; 
/**  The layer, by ID. */
layer: number } | 
/**  Switches to a layer. */
{ kind: "to-layer"; 
/**  The layer, by ID. */
layer: number } | 
/**  Turns a layer on or off. */
{ kind: "toggle"; 
/**  The layer, by ID. */
layer: number } | 
/**  A layer for the next key only. */
{ kind: "sticky-layer"; 
/**  The layer, by ID. */
layer: number } | 
/**  A key, usually a modifier, held for the next key only. */
{ kind: "sticky-key"; 
/**  The key. */
key: Shortcut } | 
/**  Same as the layer below. */
{ kind: "transparent" } | 
/**  Nothing. */
{ kind: "nothing" } | 
/**  A Bluetooth command. */
{ kind: "bluetooth"; 
/**  The command. */
command: Bluetooth; 
/**  The device it's about, from 0, for `select` and `disconnect`; otherwise 0. */
profile: number } | 
/**  Where the keyboard types. */
{ kind: "output"; 
/**  Where. */
command: Output } | 
/**  A lighting command. */
{ kind: "lighting"; 
/**  The command. */
command: Lighting } | 
/**  Power to the lights and display. */
{ kind: "external-power"; 
/**  The command. */
command: Power } | 
/**  Capitals until the end of the word. */
{ kind: "caps-word" } | 
/**  Repeats the last key. */
{ kind: "key-repeat" } | 
/**  Unlocks the keyboard for editing. */
{ kind: "unlock" } | 
/**  Puts the half into update mode. */
{ kind: "bootloader" } | 
/**  Restarts the half. */
{ kind: "reset" } | 
/**  A behavior Keywright doesn't know, with its parameters. */
{ kind: "other"; 
/**  The behavior's ID on this keyboard. */
behavior: number; 
/**  The first parameter. */
param1: Param; 
/**  The second parameter. */
param2: Param };

/**
 *  Why a command didn't do what it was asked. In TypeScript, `{ code: "not-ready" }` and
 *  so on: the codes are part of the IPC contract, so a code never changes meaning.
 */
export type AppError = 
/**  The keymap can't be changed in the session's state, such as while it's locked. */
{ code: "not-ready" } | 
/**  The keyboard is still carrying out the previous change. */
{ code: "busy" } | 
/**  There's nothing to undo. */
{ code: "nothing-to-undo" } | 
/**  There's nothing to redo. */
{ code: "nothing-to-redo" } | 
/**  Nothing has been copied to paste. */
{ code: "nothing-to-paste" } | 
/**  The editor refused an edit that doesn't fit the keymap. */
{ code: "edit-refused" } | 
/**  The keyboard didn't carry out a request, so the session rolled the change back. */
{ code: "keyboard-failed" } | 
/**  The keymap couldn't be backed up, so a destructive command changed nothing. */
{ code: "backup-failed" } | 
/**  The session has stopped, so the app has to be restarted. */
{ code: "session-stopped" } | 
/**  The menu bar didn't take a change to one of its items. */
{ code: "menu-failed" } | 
/**
 *  A layer name the keyboard can't take: too long, or with a character it can't
 *  receive (`layer_name_problem` says which).
 */
{ code: "invalid-layer-name" } | 
/**  Keywright has no stock keymap for the keyboard: it has no support pack. */
{ code: "no-stock-keymap" } | 
/**  The keyboard said it couldn't restore its stock settings. */
{ code: "reset-failed" } | 
/**  System Settings didn't open. */
{ code: "settings-not-opened" } | 
/**
 *  A setting didn't change: the menu bar didn't take the item, or the setting couldn't
 *  be saved.
 */
{ code: "setting-not-changed" } | 
/**
 *  A finding of the Mac check was dismissed, but that couldn't be saved, so it comes
 *  back once Keywright quits.
 */
{ code: "dismissal-not-saved" } | 
/**  Every key code Keywright can make act as Globe is in the keymap already (MAC-8). */
{ code: "no-globe-code" } | 
/**  macOS didn't take the Globe key's mapping, or its removal. */
{ code: "globe-not-mapped" } | 
/**
 *  The change would strand the user (SAF-2), so it wasn't applied: sent again with
 *  `force`, it is.
 */
{ code: "would-strand"; 
/**  What it would break. */
findings: GuardWarning[] };

/**  `session://battery`: a half's battery level changed, or went unreported. */
export type BatteryChanged = BatteryStatus;

/**
 *  Each half's battery level, in percent, or `null`: not reported (BAR-2). Keywright never
 *  estimates one.
 */
export type BatteryStatus = {
	/**  The left half's. */
	left: number | null,
	/**  The right half's. */
	right: number | null,
};

/**  A Bluetooth command. */
export type Bluetooth = 
/**  Forgets the pairing of the device in use. */
"clear" | 
/**  The next device. */
"next" | 
/**  The previous device. */
"previous" | 
/**  A device, by `profile`. */
"select" | 
/**  Forgets every pairing. */
"clear-all" | 
/**  Disconnects a device, by `profile`. */
"disconnect";

/**  What macOS says about Keywright using Bluetooth. */
export type BluetoothPermission = 
/**  Nobody has been asked yet. */
"not-asked" | 
/**  Keywright may use Bluetooth. */
"allowed" | 
/**  The person said no. System Settings can change it. */
"denied" | 
/**  A profile on this Mac doesn't let apps use Bluetooth. */
"restricted";

/**  A group of actions in the action picker (EDIT-1). */
export type Category = 
/**  Mac actions: Mission Control, Spotlight, Lock Screen and the like (MAC-4). */
"mac" | 
/**  Media & system: playback, volume and brightness. */
"media" | 
/**  Bluetooth & connection. */
"bluetooth" | 
/**  Lighting. */
"lighting" | 
/**  Special: Caps Word, Repeat, Unlock editing, Update mode, Restart. */
"special";

/**
 *  An action the inspector offers as it is, such as Play/Pause or Bluetooth device 1, in
 *  the words the keycap and the inspector use.
 */
export type Choice = {
	/**  The group it's listed in. */
	category: Category,
	/**  What a keycap shows for it, such as `Play/Pause` or `ᛒ 1`. */
	label: string,
	/**  What it does, in one sentence. */
	sentence: string,
	/**  The action. */
	action: Action,
	/**  The name of its icon in the UI's icon set, for a Mac action. */
	icon: string | null,
	/**
	 *  For a Mac action that relies on a default macOS shortcut, which people can change,
	 *  that shortcut, such as `⌃⌘Q` for Lock Screen (design §5.4).
	 */
	defaultShortcut: string | null,
};

/**
 *  A physical key, by its `KeyboardEvent.code`, for the shortcut recorder (MAC-2, tech
 *  spec §11.2): what the key is, whatever the input source makes it type.
 */
export type DomCode = {
	/**  The `KeyboardEvent.code` value, such as `KeyA` or `ShiftRight`. */
	code: string,
	/**  The key's usage page. */
	page: Page,
	/**  The key's usage ID. */
	id: number,
};

/**
 *  A finding of the Mac check: a key on a layer, and the key it types that doesn't work on
 *  a Mac.
 */
export type FindingRef = {
	/**  The layer, by ID. */
	layer: number,
	/**  The key, by key position. */
	position: number,
	/**  The usage page of the key it types. */
	page: Page,
	/**  That key's usage ID. */
	id: number,
};

/**  The General tab. */
export type GeneralSettings = {
	/**  _Show in menu bar_: on keeps Keywright in the menu bar when the window closes. */
	menuBar: boolean,
	/**  _Open at login_. */
	openAtLogin: OpenAtLogin,
};

/**  A group of keys in the key popup. */
export type Group = 
/**  A to Z. */
"letter" | 
/**  1 to 0. */
"number" | 
/**  Punctuation. */
"symbol" | 
/**  Return, Escape, Delete, Tab, Space and the like. */
"editing" | 
/**  Arrows, Home, End, Page Up and Page Down. */
"navigation" | 
/**  F1 to F24. */
"function" | 
/**  The numeric keypad. */
"numpad" | 
/**  The keys of Japanese, Korean and other keyboards. */
"international" | 
/**  Control, Shift, Option, Command and Caps Lock. */
"modifier" | 
/**  Playback, volume and brightness. */
"media" | 
/**  Keys that open an app or act in one. */
"application" | 
/**  Everything else. */
"other";

/**
 *  What a change would break (SAF-2). In TypeScript, `{ kind: "last-unlock-key" }` and
 *  so on.
 */
export type GuardWarning = 
/**
 *  No key could unlock the keyboard any more, so Keywright couldn't change it again
 *  until it's reset.
 */
{ kind: "last-unlock-key" } | 
/**  No key could turn the layer on any more. */
{ kind: "layer-unreachable"; 
/**  The layer, by ID. */
layer: number; 
/**  Its name. */
name: string } | 
/**  Once on the layer, there'd be no way back to the base layer. */
{ kind: "no-way-back"; 
/**  The layer, by ID. */
layer: number; 
/**  Its name. */
name: string };

/**  One key to press, in order (design §7: "① Hold Raise ② Tap B"). */
export type GuideStep = {
	/**  The key, by key position. */
	position: number,
	/**  Whether it's held while the next is pressed, rather than tapped. */
	hold: boolean,
	/**  What it's called, from the stock keymap, such as `raise` or `B`. */
	name: string,
	/**  Where it is, such as `Right half, row 5, key 2`. */
	place: string,
};

/**  A half of a split keyboard. */
export type HalfName = 
/**  The left half. */
"left" | 
/**  The right half. */
"right";

/**  What holding a tap-and-hold key does. */
export type Hold = 
/**  Holds a modifier or a key, such as `⌃`. */
{ kind: "key"; 
/**  The modifier or key. */
text: string } | 
/**  Turns a layer on. */
{ kind: "layer"; 
/**  The layer's ID, for its colour. */
layer: number; 
/**  The layer's name. */
name: string };

/**  An input source's keyboard layout. */
export type InputSource = {
	/**  Its ID, such as `com.apple.keylayout.German`. */
	id: string,
	/**  Its name, in the language the Mac is set to, such as `German`. */
	name: string,
};

/**
 *  `platform://input-source`: keys are called something else, since another input source
 *  was selected.
 */
export type InputSourceChanged = InputSource;

/**  What a key shows and does on a layer. */
export type Key = {
	/**
	 *  What it does, for the inspector's editors. A "same as layer below" key is that,
	 *  whatever it inherits.
	 */
	action: Action,
	/**  What its keycap shows. For a "same as layer below" key, what it inherits. */
	keycap: Keycap,
	/**  Whether the key is "same as layer below": its keycap is drawn faded, with a ▽. */
	inherited: boolean,
	/**  What it does, in one sentence, for its tooltip. */
	sentence: string,
	/**  The sentence for VoiceOver, with keys by name rather than symbol. */
	spoken: string,
	/**
	 *  What it types in the input source chosen for secondary labels, where that differs,
	 *  such as `Ф` (MAC-6): its keycap shows it in the top-right corner.
	 */
	secondary: string | null,
	/**  Whether it's being tried: it does something else than when last saved. */
	changed: boolean,
	/**
	 *  Whether it does something that doesn't work on a Mac (MAC-7), and the person hasn't
	 *  dismissed that.
	 */
	macWarning: boolean,
	/**
	 *  Whether it does something else than on the stock keymap, so Restore Stock would
	 *  change it (CHG-4).
	 */
	restorable: boolean,
};

/**  What [`set_keys`] makes keys do. */
export type KeyAction = 
/**  Same as the layer below (T on the canvas). */
"same-as-layer-below" | 
/**  Nothing (⌫ on the canvas). */
"does-nothing";

/**  A key the key popup offers (design §5.4), in its group. */
export type KeyEntry = {
	/**  The key's usage page. */
	page: Page,
	/**  The key's usage ID. */
	id: number,
	/**  What its keycap shows, such as `⌫`. */
	cap: string,
	/**  What text calls it, such as `Delete`. */
	name: string,
	/**  Its group. */
	group: Group,
};

/**  A key on a layer. */
export type KeyRef = {
	/**  The layer, by ID. */
	layer: number,
	/**  The key, by key position. */
	position: number,
};

/**
 *  What Keywright knows about a keyboard from its support pack, to show before the keyboard
 *  can say anything itself (design §7).
 */
export type KeyboardGuide = {
	/**  The keyboard's name, as people know it, such as `Keebart Sofle Choc Pro BT`. */
	name: string,
	/**  Its keys, as the stock firmware lays them out. */
	keys: PhysicalKey[],
	/**  The half the cable goes into, the only one that talks to the computer (CON-5). */
	usbHalf: HalfName,
	/**  How to unlock it with the stock keymap (SAF-1): hold these keys, then tap the last. */
	unlock: GuideStep[],
	/**  The key to hold, with the number keys, to pick a Bluetooth slot. */
	bluetoothHold: string | null,
};

/**
 *  What a keycap shows (design §4.2). In TypeScript, `{ kind: "label", text: "A" }` and so
 *  on.
 */
export type Keycap = 
/**  A key or shortcut, such as `A`, `⇧⌘4` or `!`, or an action in a word or two. */
{ kind: "label"; 
/**  What it says. */
text: string } | 
/**  A key when tapped, and something else when held. */
{ kind: "tap-hold"; 
/**  The key or shortcut when tapped. */
tap: string; 
/**  What holding it does. */
hold: Hold } | 
/**  A key that turns a layer on. */
{ kind: "layer"; 
/**  The layer's ID, for its colour. */
layer: number; 
/**  The layer's name. */
name: string; 
/**  How the key turns it on. */
mode: LayerMode } | 
/**  A modifier held for the next key only, such as `⇧`. */
{ kind: "sticky"; 
/**  The modifier. */
text: string } | 
/**  Nothing. */
{ kind: "nothing" } | 
/**  An action Keywright doesn't know, by the firmware's name for it. */
{ kind: "other"; 
/**  The firmware's name. */
name: string };

/**  The keymap the canvas draws: the keyboard's keys, its knobs, and its layers. */
export type Keymap = {
	/**  Where each key is, by key position. */
	keys: PhysicalKey[],
	/**  The knobs, whose turning can't be changed yet (VIEW-4). Their presses are keys. */
	knobs: Knob[],
	/**  The layers, in order: the base layer first. */
	layers: Layer[],
	/**  How many more layers the firmware has room for (LAY-3). */
	freeLayerSlots: number,
	/**  The longest layer name, in bytes of UTF-8, for the rename field's counter (LAY-1). */
	layerNameMax: number,
	/**  Whether some key the user can reach unlocks the keyboard (SAF-2). */
	unlockable: boolean,
	/**  The actions the inspector lists as they are, which the firmware can do. */
	choices: Choice[],
	/**  The behaviors Keywright doesn't know, which the inspector edits by their parameters. */
	others: OtherBehavior[],
	/**  The kinds of action the inspector edits that the firmware can do. */
	kinds: Kind[],
};

/**  `session://keymap`: the keymap the canvas draws changed, or the session has none. */
export type KeymapChanged = Keymap | null;

/**
 *  A kind of action the keyboard's firmware has a behavior for (EDIT-2): the inspector
 *  offers only those.
 */
export type Kind = 
/**  Types a key or shortcut. */
"key-press" | 
/**  A key on tap, a modifier on hold. */
"mod-tap" | 
/**  A key on tap, a layer on hold. */
"layer-tap" | 
/**  A layer while held. */
"momentary" | 
/**  Switches to a layer. */
"to-layer" | 
/**  Turns a layer on or off. */
"toggle" | 
/**  A layer for the next key. */
"sticky-layer" | 
/**  A modifier for the next key. */
"sticky-key" | 
/**  Same as the layer below. */
"transparent" | 
/**  Nothing. */
"nothing";

/**
 *  A knob: pressing it is the key at `position`, and turning it does what the support pack
 *  says the stock firmware does.
 */
export type Knob = {
	/**  The key its press is. */
	position: number,
	/**  What turning it does, one way then the other, such as `Volume Down` and `Volume Up`. */
	turn: string[],
};

/**  A layer, and what each key shows and does on it. */
export type Layer = {
	/**  The layer's ID, which picks its colour (design §4.4). */
	id: number,
	/**  Its name: its own, or `Layer 2` for an unnamed second layer. */
	name: string,
	/**  Its keys, by key position. */
	keys: Key[],
	/**  How it's reached (LAY-4): the keys that turn it on, and the firmware. */
	reach: Reach[],
	/**  Whether it's being tried: added, renamed, or with keys that are. */
	changed: boolean,
	/**  What's wrong with it (SAF-2): no key turns it on, or there's no way back from it. */
	warnings: LayerWarning[],
	/**
	 *  Whether it differs from the stock keymap, so Restore Stock Layer would change it
	 *  (CHG-4).
	 */
	restorable: boolean,
	/**
	 *  Its keys that type something that doesn't work on a Mac (MAC-7), but those the
	 *  person dismissed, in key order.
	 */
	macFindings: MacFinding[],
};

/**  How a layer key turns its layer on. */
export type LayerMode = 
/**  While the key is held. */
"hold" | 
/**  Switches to it. */
"switch" | 
/**  Turns it on or off. */
"toggle" | 
/**  For the next key only. */
"next-key";

/**  What's wrong with a layer as the keymap is now (design §5.1). */
export type LayerWarning = 
/**  No key can turn it on. */
{ kind: "unreachable" } | 
/**
 *  Once on it, there's no way back to the base layer: these keys switch to it or
 *  toggle it on, and leave it on.
 */
{ kind: "no-way-back"; 
/**  The keys, to show. */
keys: KeyRef[] };

/**  A lighting command. */
export type Lighting = 
/**  Turns the lights on or off. */
"toggle" | 
/**  Turns them on. */
"on" | 
/**  Turns them off. */
"off" | 
/**  Shifts their colour one way. */
"hue-up" | 
/**  Shifts their colour the other way. */
"hue-down" | 
/**  Makes their colour stronger. */
"saturation-up" | 
/**  Makes their colour paler. */
"saturation-down" | 
/**  Makes them brighter. */
"brightness-up" | 
/**  Makes them dimmer. */
"brightness-down" | 
/**  Speeds up their effect. */
"speed-up" | 
/**  Slows down their effect. */
"speed-down" | 
/**  The next effect. */
"next-effect" | 
/**  The previous effect. */
"previous-effect";

/**  Why Keywright can't open at login. */
export type LoginProblem = 
/**  The person has to allow it in System Settings › Login Items first. */
"requires-approval" | 
/**  macOS refused to register it. */
"refused";

/**  A key that types something that doesn't work on a Mac. */
export type MacFinding = {
	/**  The finding, to dismiss it: the key, and what it types. */
	finding: FindingRef,
	/**  Where the key is, in words, such as `Right half, row 2, key 3`. */
	place: string,
	/**  What it types, such as `Copy (Linux style)`. */
	name: string,
	/**  What goes wrong, in one sentence, such as "It doesn't do anything on a Mac." */
	reason: string,
	/**
	 *  What the key shows once fixed, such as `⌘C`, if there's a Mac replacement the
	 *  keyboard can take.
	 */
	fix: string | null,
};

/**
 *  One of Keywright's own menu items. In TypeScript, its kebab-case name, such as
 *  `"toggle-layers"`, which is also its ID in the menu.
 */
export type MenuItem = "settings" | "import" | "export" | "backups" | "update-firmware" | "undo" | "redo" | "copy-action" | "paste-action" | "select-all-keys" | "find" | "save" | "review-changes" | "discard-changes" | "record-shortcut" | "same-as-layer-below" | "does-nothing" | "restore-stock-key" | "restore-stock-settings" | "toggle-layers" | "toggle-inspector" | "layer-1" | "layer-2" | "layer-3" | "layer-4" | "layer-5" | "layer-6" | "layer-7" | "layer-8" | "layer-9" | "zoom-in" | "zoom-out" | "actual-size" | "help" | "keyboard-shortcuts" | "first-time-setup" | "report-issue";

/**  `menu://item`: someone chose one of Keywright's own menu items. */
export type MenuItemChosen = MenuItem;

/**
 *  Why a layer name can't be used (LAY-1, spike S1). In TypeScript, `{ kind: "too-long",
 *  max: 18 }` and so on.
 */
export type NameProblem = 
/**
 *  It's longer than the keyboard takes, in bytes of UTF-8: 18 letters in English,
 *  fewer in other scripts.
 */
{ kind: "too-long"; 
/**  The most bytes it can have. */
max: number } | 
/**  It has a character the keyboard's firmware can't receive, such as `Э`. */
{ kind: "character"; 
/**  The character. */
character: string };

/**  _Open at login_: whether it's on, and why it isn't, if it can't be. */
export type OpenAtLogin = {
	/**  Whether Keywright opens at login. */
	on: boolean,
	/**  Why it doesn't, though the person turned it on. */
	problem: LoginProblem | null,
};

/**
 *  A behavior Keywright doesn't know, which the inspector edits by its parameters
 *  (EDIT-2).
 */
export type OtherBehavior = {
	/**  Its ID on this keyboard. */
	id: number,
	/**  The firmware's name for it. */
	name: string,
	/**  The combinations of parameters it accepts: a binding must match one. */
	parameters: ParameterSet[],
};

/**  Where the keyboard types. */
export type Output = 
/**  Switches between USB and Bluetooth. */
"toggle" | 
/**  USB. */
"usb" | 
/**  Bluetooth. */
"bluetooth";

/**  A usage page ZMK can send. */
export type Page = 
/**  Keyboard keys. */
"keyboard" | 
/**  Consumer controls, such as media keys. */
"consumer";

/**
 *  A parameter of a behavior Keywright doesn't know: a number, or a key where the
 *  behavior's metadata says it takes one, so the UI never encodes keys itself.
 */
export type Param = 
/**  A number: a named constant, a number in a range, or a layer's ID. */
{ kind: "number"; 
/**  The number. */
value: number } | 
/**  A key or shortcut. */
{ kind: "key"; 
/**  The key or shortcut. */
key: Shortcut };

/**  Values a behavior's two parameters accept together. */
export type ParameterSet = {
	/**  What the first accepts: any one of them. None means it must be 0. */
	param1: ParameterValue[],
	/**  What the second accepts, as for the first. */
	param2: ParameterValue[],
};

/**  A value, or a kind of value, a parameter accepts. */
export type ParameterValue = {
	/**  What the firmware calls it. It can be empty. */
	name: string,
	/**  The values it covers. */
	value: Value,
};

/**
 *  A key's place, size and rotation, as the keyboard reports them. Lengths are in
 *  hundredths of a key unit, and angles in hundredths of a degree, clockwise.
 */
export type PhysicalKey = {
	/**  The left edge. */
	x: number,
	/**  The top edge. */
	y: number,
	/**  The width. */
	width: number,
	/**  The height. */
	height: number,
	/**  The rotation. */
	rotation: number,
	/**  The x coordinate of the point the key rotates around. */
	rotationX: number,
	/**  The y coordinate of the point the key rotates around. */
	rotationY: number,
	/**
	 *  Where the key is, in words, for VoiceOver: `Left half, row 3, key 1`, or `Key 12`
	 *  on a keyboard without a support pack.
	 */
	place: string,
};

/**  A command for the power to the lights and display. */
export type Power = 
/**  Turns it on or off. */
"toggle" | 
/**  Turns it on. */
"on" | 
/**  Turns it off. */
"off";

/**  Why a keyboard is incompatible. */
export type Problem = 
/**  The keyboard doesn't handle a request Keywright needs. */
"unsupported" | 
/**  The keyboard didn't answer a request, twice. */
"no-answer" | 
/**  The keyboard answered a request with something else. */
"unexpected-answer";

/**
 *  `app://quit-requested`: someone asked to quit, or to close the window, while changes are
 *  being tried. The UI asks whether to save them.
 */
export type QuitRequested = null;

/**  One way to reach a layer (LAY-4), such as "Hold lower". */
export type Reach = {
	/**  How, in words. */
	text: string,
	/**  The key that does it, by key position, if a key does. */
	position: number | null,
	/**  Where that key is, in words, such as `Left half, row 5, key 4`. */
	place: string | null,
};

/**
 *  One row of the review sheet (design §6): what changed, how it was when saved, and how
 *  it is now.
 */
export type ReviewRow = {
	/**  What it's about, to take it back. */
	key: RowKey,
	/**  The layer it's listed under, by ID and name, unless it's the layers' order. */
	layer: number | null,
	/**  That layer's name. */
	layerName: string | null,
	/**  Where the key is, for a key, such as `Left half, row 2, key 1`. */
	place: string | null,
	/**  How it was when saved, as a keycap shows it or in a word or two. */
	before: string,
	/**  How it is now. */
	after: string,
	/**  What it does now, in a sentence, for a key. */
	sentence: string | null,
};

/**
 *  What a review row is about: the order of the layers, a layer, or a key on one. In
 *  TypeScript, `{ kind: "key", layer: 0, position: 13 }` and so on.
 */
export type RowKey = 
/**  The layers' order. */
{ kind: "order" } | 
/**  A layer that's new. */
{ kind: "added"; 
/**  The layer. */
layer: number } | 
/**  A layer that's gone. */
{ kind: "removed"; 
/**  The layer. */
layer: number } | 
/**  A layer's name. */
{ kind: "renamed"; 
/**  The layer. */
layer: number } | 
/**  A key on a layer. */
{ kind: "key"; 
/**  The layer. */
layer: number; 
/**  The key. */
position: number };

/**
 *  Settings › Keyboard's secondary labels (MAC-6): the input source chosen, and those to
 *  choose from.
 */
export type SecondaryLabels = {
	/**  The input source chosen, by ID, if one is. */
	chosen: string | null,
	/**  The keyboard layouts turned on in System Settings, as the input menu lists them. */
	layouts: InputSource[],
};

/**
 *  What the session is doing (tech spec §7.1). In TypeScript, `{ kind: "ready" }` and so
 *  on.
 */
export type SessionState = 
/**  No keyboard is connected. */
{ kind: "no-device" } | 
/**  The session is asking the keyboard what it is. */
{ kind: "probing" } | 
/**  The keyboard is locked: someone has to press its unlock keys. */
{ kind: "locked" } | 
/**  The session is reading the keymap. */
{ kind: "loading" } | 
/**  The keyboard has unsaved changes from before this session, to keep or discard. */
{ kind: "unsaved-changes" } | 
/**  The keymap can be changed. */
{ kind: "ready" } | 
/**
 *  The keyboard restarted and forgot the changes being tried, to apply again or
 *  discard.
 */
{ kind: "changes-lost" } | 
/**  The keyboard answers, but not as Keywright expects, so it can't be edited. */
{ kind: "incompatible"; 
/**  What went wrong. */
problem: Problem; 
/**
 *  The protocol's name for the request, for diagnostics: the default UI doesn't
 *  show it (design §11).
 */
request: string } | 
/**  A keyboard is there, but has no live editing over this connection. */
{ kind: "no-live-editing" } | 
/**  The half of a split keyboard that isn't the one connected to the computer. */
{ kind: "wrong-half" };

/**  `session://state`: the session's status changed. */
export type SessionStateChanged = SessionStatus;

/**
 *  The session's status: its state, the keyboard it's connected to and how, and how
 *  many changes are being tried.
 */
export type SessionStatus = {
	/**  What the session is doing. */
	state: SessionState,
	/**  The keyboard's name, as its firmware reports it, once the session knows it. */
	keyboard: string | null,
	/**  The ID of the keyboard's support pack, if Keywright has one for it. */
	pack: string | null,
	/**  How the session reaches the keyboard, once it knows. */
	transport: Transport | null,
	/**  How many changes are being tried and not saved: the rows of the review list. */
	changes: number,
	/**  Whether there's a change to undo. */
	canUndo: boolean,
	/**  Whether there's a change undone to redo. */
	canRedo: boolean,
	/**  What undo would take back, in a few words, for the Edit menu: "Assign ⌘C to B". */
	undo: string | null,
	/**  What redo would apply again, in a few words. */
	redo: string | null,
};

/**  A key or shortcut: a key, with modifiers held. */
export type Shortcut = {
	/**
	 *  The modifiers held, as ZMK's bits: 1 left Control, 2 left Shift, 4 left Option, 8
	 *  left Command, then 16 to 128 for the right ones.
	 */
	mods: number,
	/**  The key's usage page. */
	page: Page,
	/**  The key's usage ID on its page. */
	id: number,
};

/**
 *  What a key or shortcut is called (design §5.3): on a keycap, in text, and the Mac
 *  action it is, if it's one.
 */
export type ShortcutWords = {
	/**  As a keycap shows it, such as `⇧⌘4`. */
	label: string,
	/**  As text calls it, such as `Escape`. */
	name: string,
	/**  The Mac action preset it is, such as `Screenshot of an area`, if it's one. */
	preset: string | null,
};

/**
 *  A standard text-editing action, for Edit's items while a text field has focus (design
 *  §9.6): they act on keys otherwise.
 */
export type TextEdit = 
/**  Undo (⌘Z). */
"undo" | 
/**  Redo (⇧⌘Z). */
"redo" | 
/**  Copy (⌘C). */
"copy" | 
/**  Paste (⌘V). */
"paste" | 
/**  Select All (⌘A). */
"select-all";

/**
 *  `window://traffic-lights`: where the main window's traffic lights end moved, in points
 *  from its left edge, or they're hidden (`null`).
 */
export type TrafficLightsMoved = number | null;

/**  How the session reaches the keyboard. */
export type Transport = 
/**  A USB cable. */
"usb" | 
/**  Bluetooth. */
"bluetooth" | 
/**  A simulated keyboard, in the same process. */
"simulated";

/**
 *  The values a parameter value covers. In TypeScript, `{ kind: "range", min, max }` and so
 *  on.
 */
export type Value = 
/**  Only 0. */
{ kind: "nil" } | 
/**  Exactly this number. */
{ kind: "constant"; 
/**  The number. */
value: number } | 
/**  Any number from `min` to `max`. */
{ kind: "range"; 
/**  The smallest. */
min: number; 
/**  The largest. */
max: number } | 
/**  A key or shortcut. */
{ kind: "key" } | 
/**  A layer, by ID. */
{ kind: "layer" };

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

